namespace ghidra.app.plugin.core.codebrowser.hover;




using docking.widgets.fieldpanel.field;
using docking.widgets.fieldpanel.support;
using ghidra;
using ghidra.app.plugin.core.hover;
using ghidra.app.util;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.util;

/**
 * A Listing hover to show tool tips for function signatures
 */
public class FunctionSignatureListingHover : AbstractConfigurableHover, ListingHoverService {

	private static readonly string NAME = "Function Signature Display";
	private static readonly string DESCRIPTION =
		"Toggle whether function signature is displayed in a tooltip " +
			"when the mouse hovers over a function signature.";

	// note: guilty knowledge that the Truncated Text service has a priority of 10
	private static readonly int POPUP_PRIORITY = 20;

	public FunctionSignatureListingHover(PluginTool tool) : base(tool, POPUP_PRIORITY)
    {
	}

	/* @Override */
	protected string getName() {
		return NAME;
	}

	/* @Override */
	protected string getDescription() {
		return DESCRIPTION;
	}

	/* @Override */
	protected string getOptionsCategory() {
		return GhidraOptions.CATEGORY_BROWSER_POPUPS;
	}

	/* @Override */
	public JComponent getHoverComponent(Program program, ProgramLocation programLocation,
			FieldLocation fieldLocation, Field field) {

		if (!enabled || programLocation == null) {
			return null;
		}

		Class<ProgramLocation> clazz = programLocation.GetType();
		if (clazz != typeof(FunctionSignatureFieldLocation) &&
			clazz != typeof(FunctionNameFieldLocation)) {
			return null;
		}

		// is the label local to the function
		FunctionSignatureFieldLocation functionLocation =
			(FunctionSignatureFieldLocation) programLocation;

		Address entry = functionLocation.getFunctionAddress();
		FunctionManager functionManager = program.getFunctionManager();
		Function function = functionManager.getFunctionAt(entry);

		string toolTipText = ToolTipUtils.getToolTipText(function, true);
		JToolTip toolTip = new JToolTip();
		toolTip.setTipText(toolTipText);
		return toolTip;
	}

}
